import java.sql.Connection;
import java.sql.PreparedStatement;

public class Login {
    public void doPost(String username, String password) throws Exception {
        // Input validation and sanitization
        String username = request.getParameter("username");
        String password = request.getParameter("password");
        validateUsername(username);
        validatePassword(password);

        // Using parameterized query to prevent SQL Injection
        String sql = "SELECT * FROM users WHERE username =? AND password =?";
        try (Connection con = getConnection(); PreparedStatement stmt = con.prepareStatement(sql)) {
            stmt.setString(1, username);
            stmt.setString(2, password);
            stmt.execute();
        }
    }

    private void validateUsername(String username) {
        // Basic validation to ensure the username is not null and has a minimum length
        if (username == null || username.trim() == "") {
            throw new Exception("Invalid username");
        }
        if (username.length() < 5) {
            throw new Exception("Username must be at least 5 characters long");
        }
    }

    private void validatePassword(String password) {
        // Basic validation to ensure the password is not null and has a minimum length
        if (password == null || password.trim() == "") {
            throw new Exception("Invalid password");
        }
        if (password.length() < 8) {
            throw new Exception("Password must be at least 8 characters long");
        }
    }
}
```

